import { adjustStock, inventoryView } from './employee-store-model.js';
const clone=v=>JSON.parse(JSON.stringify(v)); const text=v=>String(v??'').trim();
function base(input){const releaseId=text(input.releaseId),jobId=text(input.jobId),itemId=text(input.itemId),actor=text(input.actor),key=text(input.idempotencyKey),quantity=Number(input.quantity);if(!releaseId||!jobId||!itemId||!actor||!key)throw new Error('Libération, tâche, article, employé et clé opération requis');if(!Number.isFinite(quantity)||quantity<=0)throw new Error('Quantité atelier invalide');if(input.authorized!==true)throw new Error('Autorisation atelier requise');return{releaseId,jobId,itemId,actor,key,quantity}}
export function issueWorkshopMaterial(store,input,{expectedRevision,now=new Date()}={}){const x=base(input);const idempotencyKey=`workshop-issue:${x.releaseId}:${x.jobId}:${x.key}`;const available=inventoryView(store,x.itemId).available;if(x.quantity>available+1e-9)throw new Error('Stock disponible insuffisant; réservations employés protégées');const before=store.revision;let next=adjustStock(store,{itemId:x.itemId,delta:-x.quantity,idempotencyKey,reason:`Sortie atelier ${x.releaseId}/${x.jobId}`,actorRole:'admin'},{expectedRevision,now});if(next.revision!==before)Object.assign(next.events.at(-1),{source:'workshop-issue',releaseId:x.releaseId,jobId:x.jobId,actor:x.actor});return{store:next,duplicate:next.revision===before,itemId:x.itemId,quantity:x.quantity,inventory:inventoryView(next,x.itemId)}}
export function returnWorkshopMaterial(store,input,{expectedRevision,now=new Date()}={}){const x=base(input);const idempotencyKey=`workshop-return:${x.releaseId}:${x.jobId}:${x.key}`;const before=store.revision;let next=adjustStock(store,{itemId:x.itemId,delta:x.quantity,idempotencyKey,reason:`Retour atelier ${x.releaseId}/${x.jobId}`,actorRole:'admin'},{expectedRevision,now});if(next.revision!==before)Object.assign(next.events.at(-1),{source:'workshop-return',releaseId:x.releaseId,jobId:x.jobId,actor:x.actor});return{store:next,duplicate:next.revision===before,itemId:x.itemId,quantity:x.quantity,inventory:inventoryView(next,x.itemId)}}
export function workshopInventorySummary(store,{releaseId='',jobId=''}={}){const movements=(store.events||[]).filter(e=>['workshop-issue','workshop-return'].includes(e.source)&&(!releaseId||e.releaseId===releaseId)&&(!jobId||e.jobId===jobId));return{movements:clone(movements),issued:movements.filter(x=>x.source==='workshop-issue').reduce((s,x)=>s+Math.abs(Number(x.delta)||0),0),returned:movements.filter(x=>x.source==='workshop-return').reduce((s,x)=>s+Math.abs(Number(x.delta)||0),0)}}
